const body = $input.first().json.body || {};
// Slack URL verification handshake
if (body.type === 'url_verification') return [{ json: { respond: body.challenge, act: false } }];
const ev = body.event || {};
// only direct messages from humans (no bot echoes)
if (ev.type !== 'message' || ev.channel_type !== 'im' || ev.bot_id || !ev.text) return [{ json: { respond: 'ok', act: false } }];
const m = String(ev.text).trim().match(/^(done|not a risk|not risk|dismiss)\s+(\d)/i);
if (!m) return [{ json: { respond: 'ok', act: false, unknown: true, user: ev.user, channel: ev.channel, text: String(ev.text).slice(0, 200) } }];
const action = /done/i.test(m[1]) ? 'done' : 'not_a_risk';
return [{ json: { respond: 'ok', act: true, action, item_no: Number(m[2]), user: ev.user, channel: ev.channel } }];

const p = $('Parse reply').first().json;
const rows = $input.all().map((x) => x.json);
if (!p.act) return [{ json: { message: null } }];
const hit = rows.find((r) => Number(r.item_no) === Number(p.item_no));
if (!hit || !hit.signal_id) return [{ json: { channel: p.channel, message: 'I could not find item ' + p.item_no + ' from your latest brief - it may have been superseded by a newer one.' } }];
const e = (s) => String(s).split("'").join("''");
const sql = p.action === 'done'
  ? "UPDATE signals SET status = 'actioned' WHERE id = '" + e(hit.signal_id) + "';"
  : "INSERT INTO feedback (signal_id, account_id, verdict, reason, given_by) SELECT id, account_id, 'incorrect', 'Marked not a risk from the Slack brief', 'Kiera Battersby' FROM signals WHERE id = '" + e(hit.signal_id) + "'; UPDATE signals SET status = 'dismissed' WHERE id = '" + e(hit.signal_id) + "';";
const message = p.action === 'done'
  ? ':white_check_mark: Marked item ' + p.item_no + ' as actioned - it moves to the Resolved panel.'
  : ':x: Removed item ' + p.item_no + ' and taught the brain it was not a risk.';
return [{ json: { channel: p.channel, sql, message } }];
